CREATE TABLE form_definition (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), form_key varchar(100) NOT NULL, object_key varchar(100) NOT NULL, version integer NOT NULL, active boolean NOT NULL DEFAULT true, definition jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(form_key, version));
CREATE TABLE automation_rule (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_key varchar(100) NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT false, definition jsonb NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sla_policy (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), policy_key varchar(100) NOT NULL UNIQUE, enabled boolean NOT NULL DEFAULT true, definition jsonb NOT NULL, version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rbac_grant (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type varchar(30) NOT NULL, subject_id varchar(128) NOT NULL, permission varchar(150) NOT NULL, object_type varchar(100), scope jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX rbac_grant_lookup_idx ON rbac_grant(subject_type, subject_id, permission);
